(2, 'wrong_answer_penalty', '5', 'integer', 'Penalti Jawaban Salah', 'Poin yang dikurangi saat pemain menjawab soal dengan salah atau tidak menjawab hingga waktu habis. Disimpan sebagai nilai positif, dikurangkan oleh sistem.', 'Skor', '2026-07-12 12:36:58', '2026-07-16 01:44:17'),
