(4, 'tile_penalty_point', '5', 'integer', 'Penalti Petak Penalti/Mystery', 'Poin yang dikurangi saat mendarat di petak Penalti atau efek negatif dari petak Mystery. Terpisah dari penalti jawaban salah. Disimpan sebagai nilai positif, dikurangkan oleh sistem.', 'Skor', '2026-07-12 12:36:58', '2026-07-12 12:36:58'),
(5, 'win_point', '100', 'integer', 'Poin Kemenangan', 'Poin tambahan yang didapat pemain saat memenangkan permainan (mencapai petak Finish).', 'Skor', '2026-07-12 12:36:58', '2026-07-12 12:36:58'),
