(7, 'reconnect_timeout_seconds', '60', 'integer', 'Timeout Reconnect Multiplayer (detik)', 'Batas waktu bagi pemain yang terputus koneksi untuk kembali sebelum dinyatakan forfeit (kalah WO).', 'Timer', '2026-07-12 12:36:58', '2026-07-12 12:36:58'),
(8, 'heartbeat_timeout_seconds', '15', 'integer', 'Batas Diam Heartbeat (detik)', 'Jika klien multiplayer tidak mengirim heartbeat selama durasi ini, pemain dianggap terputus koneksi dan permainan dijeda.', 'Timer', '2026-07-12 12:36:58', '2026-07-12 12:36:58'),
(9, 'room_waiting_expiry_minutes', '5', 'integer', 'Timeout Room Menunggu (menit)', 'Room Quick Match/Private yang belum terisi lawan dalam durasi ini otomatis dibatalkan (Abandoned).', 'Timer', '2026-07-12 12:36:58', '2026-07-12 12:36:58');

