--
-- Struktur dari tabel `soal`
--

CREATE TABLE `soal` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `kategori_id` bigint(20) UNSIGNED NOT NULL,
  `pertanyaan` text NOT NULL,
  `opsi_jawaban` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`opsi_jawaban`)),
  `kunci_jawaban` varchar(255) NOT NULL,
  `pembahasan` text NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dumping data untuk tabel `soal`
--

INSERT INTO `soal` (`id`, `kategori_id`, `pertanyaan`, `opsi_jawaban`, `kunci_jawaban`, `pembahasan`, `is_active`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 1, 'Data ujian 5 siswa adalah 70, 80, 90, 60, 100. Berapakah nilai mean (rata-rata) dari data tersebut?', '{\"A\":\"70\",\"B\":\"75\",\"C\":\"80\",\"D\":\"85\"}', 'C', 'Mean dihitung dengan menjumlahkan semua nilai lalu membaginya dengan banyaknya data: (70+80+90+60+100)/5 = 400/5 = 80.', 1, '2026-07-12 12:36:58', '2026-07-12 12:36:58', NULL),
(2, 1, 'Data terurut: 3, 5, 7, 9, 11. Berapakah median dari data tersebut?', '{\"A\":\"5\",\"B\":\"7\",\"C\":\"9\",\"D\":\"11\"}', 'B', 'Karena banyaknya data ganjil (5 data), median adalah nilai tepat di tengah setelah diurutkan, yaitu 7.', 1, '2026-07-12 12:36:58', '2026-07-12 12:36:58', NULL),
(3, 1, 'Dalam sekumpulan data nilai ulangan: 7, 8, 8, 9, 8, 6, 8, berapakah modusnya?', '{\"A\":\"6\",\"B\":\"7\",\"C\":\"8\",\"D\":\"9\"}', 'C', 'Modus adalah nilai yang paling sering muncul. Angka 8 muncul 4 kali, lebih banyak dari angka lainnya.', 1, '2026-07-12 12:36:58', '2026-07-12 12:36:58', NULL),
(4, 1, 'Grafik apa yang paling cocok digunakan untuk menunjukkan tren inflasi bulanan selama satu tahun?', '{\"A\":\"Diagram lingkaran\",\"B\":\"Grafik garis\",\"C\":\"Grafik batang\",\"D\":\"Tabel frekuensi\"}', 'B', 'Grafik garis paling cocok untuk menunjukkan perubahan/tren suatu nilai dari waktu ke waktu, seperti inflasi bulanan.', 1, '2026-07-12 12:36:58', '2026-07-12 12:36:58', NULL),
(5, 1, 'Manakah pernyataan yang benar mengenai perbedaan statistik dan statistika?', '{\"A\":\"Statistik adalah ilmunya, statistika adalah datanya\",\"B\":\"Statistik adalah datanya, statistika adalah ilmunya\",\"C\":\"Keduanya memiliki arti yang sama persis\",\"D\":\"Statistik hanya dipakai di bidang ekonomi\"}', 'B', 'Statistik merujuk pada kumpulan data/angka, sedangkan statistika adalah ilmu yang mempelajari cara mengolah data tersebut.', 1, '2026-07-12 12:36:58', '2026-07-12 12:36:58', NULL),
(6, 1, 'Cabang statistika yang berfokus pada penarikan kesimpulan tentang populasi berdasarkan sampel disebut...', '{\"A\":\"Statistika deskriptif\",\"B\":\"Statistika inferensia\",\"C\":\"Statistika terapan\",\"D\":\"Statistika non-parametrik\"}', 'B', 'Statistika inferensia digunakan untuk menarik kesimpulan atau membuat prediksi tentang populasi berdasarkan data sampel.', 1, '2026-07-12 12:36:58', '2026-07-12 12:36:58', NULL),
(7, 1, 'Data nilai ujian: 60, 65, 70, 75, 90. Berapakah range (jangkauan) dari data tersebut?', '{\"A\":\"20\",\"B\":\"25\",\"C\":\"30\",\"D\":\"90\"}', 'C', 'Range dihitung dari nilai maksimum dikurangi nilai minimum: 90 - 60 = 30.', 1, '2026-07-12 12:36:58', '2026-07-12 12:36:58', NULL),
(8, 1, 'Ukuran yang menunjukkan seberapa jauh sebaran data terhadap nilai rata-ratanya disebut...', '{\"A\":\"Modus\",\"B\":\"Median\",\"C\":\"Standar deviasi\",\"D\":\"Frekuensi\"}', 'C', 'Standar deviasi mengukur sebaran/variasi data terhadap nilai rata-rata (mean); semakin besar nilainya, semakin tersebar datanya.', 1, '2026-07-12 12:36:58', '2026-07-12 12:36:58', NULL),
(9, 1, 'Data seperti \"warna favorit\" dan \"jenis kelamin\" termasuk jenis data...', '{\"A\":\"Kuantitatif diskrit\",\"B\":\"Kuantitatif kontinu\",\"C\":\"Kualitatif\",\"D\":\"Data time series\"}', 'C', 'Data kualitatif berupa kategori/label (bukan angka), seperti warna favorit atau jenis kelamin.', 1, '2026-07-12 12:36:58', '2026-07-12 12:36:58', NULL),
(10, 1, 'Sebagian kecil anggota populasi yang diambil untuk mewakili keseluruhan populasi disebut...', '{\"A\":\"Sensus\",\"B\":\"Sampel\",\"C\":\"Parameter\",\"D\":\"Variabel\"}', 'B', 'Sampel adalah sebagian anggota populasi yang dipilih untuk mewakili karakteristik keseluruhan populasi.', 1, '2026-07-12 12:36:58', '2026-07-12 12:36:58', NULL),
(11, 1, 'Diagram lingkaran (pie chart) paling cocok digunakan untuk menampilkan...', '{\"A\":\"Tren data dari waktu ke waktu\",\"B\":\"Proporsi\\/persentase tiap kategori terhadap keseluruhan\",\"C\":\"Hubungan dua variabel numerik\",\"D\":\"Urutan data dari terkecil ke terbesar\"}', 'B', 'Diagram lingkaran menunjukkan proporsi atau persentase setiap kategori terhadap total keseluruhan data.', 1, '2026-07-12 12:36:58', '2026-07-12 12:36:58', NULL),
(12, 1, 'Nilai yang membagi data terurut menjadi empat bagian sama besar disebut...', '{\"A\":\"Persentil\",\"B\":\"Kuartil\",\"C\":\"Desil\",\"D\":\"Modus\"}', 'B', 'Kuartil membagi data yang sudah terurut menjadi empat bagian sama besar (Q1, Q2/median, dan Q3).', 1, '2026-07-12 12:36:58', '2026-07-12 12:36:58', NULL),
(13, 2, 'Apa kepanjangan dari BPS?', '{\"A\":\"Badan Pusat Statistik\",\"B\":\"Biro Pusat Survei\",\"C\":\"Badan Perencanaan Statistik\",\"D\":\"Badan Pengelola Sensus\"}', 'A', 'BPS adalah singkatan dari Badan Pusat Statistik, lembaga pemerintah non-kementerian yang menyelenggarakan statistik nasional.', 1, '2026-07-12 12:36:58', '2026-07-12 12:36:58', NULL),
(14, 2, 'Setiap tanggal berapa Hari Statistik Nasional diperingati di Indonesia?', '{\"A\":\"17 Agustus\",\"B\":\"26 September\",\"C\":\"10 November\",\"D\":\"1 Januari\"}', 'B', 'Hari Statistik Nasional diperingati setiap tanggal 26 September untuk mengenang lahirnya lembaga statistik resmi di Indonesia.', 1, '2026-07-12 12:36:58', '2026-07-12 12:36:58', NULL),
(15, 2, 'Sensus Penduduk di Indonesia dilaksanakan setiap berapa tahun sekali?', '{\"A\":\"5 tahun\",\"B\":\"10 tahun\",\"C\":\"15 tahun\",\"D\":\"20 tahun\"}', 'B', 'Sensus Penduduk dilaksanakan setiap 10 tahun sekali, pada tahun yang berakhiran angka 0 (misalnya 2020, 2030).', 1, '2026-07-12 12:36:58', '2026-07-12 12:36:58', NULL),
(16, 2, 'Sensus Ekonomi dilaksanakan pada tahun yang berakhiran angka berapa?', '{\"A\":\"0\",\"B\":\"3\",\"C\":\"6\",\"D\":\"9\"}', 'C', 'Sensus Ekonomi dilaksanakan setiap 10 tahun pada tahun berakhiran angka 6, misalnya 2016 dan 2026.', 1, '2026-07-12 12:36:58', '2026-07-12 12:36:58', NULL),
(17, 2, 'Survei BPS yang digunakan untuk mengukur kondisi ketenagakerjaan disebut...', '{\"A\":\"Susenas\",\"B\":\"Sakernas\",\"C\":\"Podes\",\"D\":\"SUPAS\"}', 'B', 'Sakernas (Survei Angkatan Kerja Nasional) digunakan BPS untuk mengukur kondisi ketenagakerjaan, termasuk tingkat pengangguran.', 1, '2026-07-12 12:36:58', '2026-07-12 12:36:58', NULL),
(18, 2, 'Apa perbedaan utama antara sensus dan survei?', '{\"A\":\"Sensus mendata seluruh populasi, survei menggunakan sampel\",\"B\":\"Survei mendata seluruh populasi, sensus menggunakan sampel\",\"C\":\"Keduanya selalu mendata seluruh populasi\",\"D\":\"Tidak ada perbedaan, istilah yang sama\"}', 'A', 'Sensus mendata seluruh unit populasi, sedangkan survei menggunakan sampel yang mewakili populasi agar lebih efisien.', 1, '2026-07-12 12:36:58', '2026-07-12 12:36:58', NULL),
(19, 2, 'Apa status kelembagaan BPS di pemerintahan Indonesia?', '{\"A\":\"Kementerian\",\"B\":\"Lembaga Pemerintah Non-Kementerian (LPNK)\",\"C\":\"Badan Usaha Milik Negara\",\"D\":\"Lembaga Swadaya Masyarakat\"}', 'B', 'BPS adalah Lembaga Pemerintah Non-Kementerian (LPNK) yang bertanggung jawab langsung kepada Presiden.', 1, '2026-07-12 12:36:58', '2026-07-12 12:36:58', NULL),
(20, 2, 'Pendataan Potensi Desa yang dilakukan BPS untuk mengetahui potensi wilayah administrasi terkecil disebut...', '{\"A\":\"Susenas\",\"B\":\"Sakernas\",\"C\":\"Podes\",\"D\":\"SUPAS\"}', 'C', 'Podes (Pendataan Potensi Desa) mengumpulkan data potensi desa/kelurahan di seluruh Indonesia.', 1, '2026-07-12 12:36:58', '2026-07-12 12:36:58', NULL),
(21, 2, 'Survei Sosial Ekonomi Nasional yang mengukur kesejahteraan rumah tangga dikenal dengan singkatan...', '{\"A\":\"Susenas\",\"B\":\"Sakernas\",\"C\":\"SPTN\",\"D\":\"ST\"}', 'A', 'Susenas (Survei Sosial Ekonomi Nasional) digunakan untuk mengukur tingkat kesejahteraan rumah tangga.', 1, '2026-07-12 12:36:58', '2026-07-12 12:36:58', NULL),
(22, 2, 'Sensus Penduduk Indonesia tahun 2020 (SP2020) untuk pertama kalinya menggunakan metode kombinasi data...', '{\"A\":\"Wawancara tatap muka saja\",\"B\":\"Registrasi penduduk dan sensus lapangan\",\"C\":\"Survei telepon saja\",\"D\":\"Estimasi tanpa data lapangan\"}', 'B', 'SP2020 menggunakan metode kombinasi, memanfaatkan data registrasi penduduk (Dukcapil) yang dilengkapi sensus lapangan.', 1, '2026-07-12 12:36:58', '2026-07-12 12:36:58', NULL),
(23, 2, 'Publikasi tahunan BPS yang memuat rangkuman data statistik seluruh Indonesia berjudul...', '{\"A\":\"Statistik Indonesia\",\"B\":\"Berita Resmi Statistik\",\"C\":\"Buku Saku BPS\",\"D\":\"Indikator Ekonomi\"}', 'A', '\"Statistik Indonesia\" adalah publikasi tahunan BPS yang merangkum data statistik dari berbagai bidang di seluruh Indonesia.', 1, '2026-07-12 12:36:58', '2026-07-12 12:36:58', NULL),
(24, 2, 'Apa fungsi utama Berita Resmi Statistik (BRS) yang rutin dirilis BPS?', '{\"A\":\"Mengumumkan hasil rilis data terbaru secara resmi dan berkala kepada publik\",\"B\":\"Mengumumkan kebijakan anggaran pemerintah\",\"C\":\"Menyampaikan hasil pemilu\",\"D\":\"Mengatur kurikulum pendidikan statistik\"}', 'A', 'BRS adalah rilis resmi dan berkala (misalnya inflasi bulanan atau pertumbuhan ekonomi triwulanan) yang dipublikasikan BPS ke masyarakat.', 1, '2026-07-12 12:36:58', '2026-07-12 12:36:58', NULL),
(25, 2, 'Semboyan/motto BPS adalah \"Penyedia Data Statistik Terpercaya untuk ...\"', '{\"A\":\"Pemerintah\",\"B\":\"Semua\",\"C\":\"Peneliti\",\"D\":\"Dunia Usaha\"}', 'B', 'Motto BPS adalah \"Penyedia Data Statistik Terpercaya untuk Semua\", menegaskan data BPS terbuka dan dapat diandalkan oleh siapa saja.', 1, '2026-07-12 12:36:58', '2026-07-12 12:36:58', NULL),
(26, 3, 'Apa kepanjangan dari IPM?', '{\"A\":\"Indeks Pertumbuhan Masyarakat\",\"B\":\"Indeks Pembangunan Manusia\",\"C\":\"Indikator Produksi Masyarakat\",\"D\":\"Indeks Perekonomian Modern\"}', 'B', 'IPM adalah singkatan dari Indeks Pembangunan Manusia (Human Development Index).', 1, '2026-07-12 12:36:58', '2026-07-12 12:36:58', NULL),
(27, 3, 'Manakah yang BUKAN merupakan dimensi penyusun IPM?', '{\"A\":\"Umur panjang dan hidup sehat\",\"B\":\"Pengetahuan\",\"C\":\"Standar hidup layak\",\"D\":\"Jumlah penduduk\"}', 'D', 'IPM disusun dari tiga dimensi: umur panjang dan hidup sehat, pengetahuan, dan standar hidup layak. Jumlah penduduk bukan salah satu dimensinya.', 1, '2026-07-12 12:36:58', '2026-07-12 12:36:58', NULL),
(28, 3, 'Apa kepanjangan dari PDRB?', '{\"A\":\"Produk Domestik Regional Bruto\",\"B\":\"Pendapatan Daerah Regional Bersih\",\"C\":\"Produksi Dalam Rangka Bisnis\",\"D\":\"Perhitungan Data Regional Bersama\"}', 'A', 'PDRB adalah singkatan dari Produk Domestik Regional Bruto, nilai total barang dan jasa yang dihasilkan di suatu wilayah.', 1, '2026-07-12 12:36:58', '2026-07-12 12:36:58', NULL),
(29, 3, 'Tingkat Pengangguran Terbuka (TPT) mengukur persentase pengangguran terhadap...', '{\"A\":\"Jumlah penduduk\",\"B\":\"Angkatan kerja\",\"C\":\"Jumlah rumah tangga\",\"D\":\"Penduduk usia sekolah\"}', 'B', 'TPT adalah persentase jumlah pengangguran terhadap total angkatan kerja (penduduk usia kerja yang bekerja atau mencari kerja).', 1, '2026-07-12 12:36:58', '2026-07-12 12:36:58', NULL),
(30, 3, 'Apa yang dimaksud dengan inflasi?', '{\"A\":\"Penurunan harga barang secara umum dan terus-menerus\",\"B\":\"Kenaikan harga barang secara umum dan terus-menerus\",\"C\":\"Kenaikan jumlah penduduk secara drastis\",\"D\":\"Penurunan jumlah pengangguran\"}', 'B', 'Inflasi adalah kecenderungan kenaikan harga barang dan jasa secara umum dan terus-menerus dalam periode tertentu.', 1, '2026-07-12 12:36:58', '2026-07-12 12:36:58', NULL),
(31, 3, 'BPS mengukur inflasi berdasarkan perubahan indeks apa?', '{\"A\":\"Indeks Pembangunan Manusia\",\"B\":\"Indeks Harga Konsumen\",\"C\":\"Indeks Ketimpangan Gini\",\"D\":\"Indeks Produksi Industri\"}', 'B', 'BPS mengukur inflasi melalui Indeks Harga Konsumen (IHK) yang memantau perubahan harga barang/jasa yang dikonsumsi rumah tangga.', 1, '2026-07-12 12:36:58', '2026-07-12 12:36:58', NULL),
(32, 3, 'Indikator yang mengukur tingkat ketimpangan pengeluaran/pendapatan penduduk disebut...', '{\"A\":\"Gini Ratio\",\"B\":\"Indeks Harga Konsumen\",\"C\":\"Nilai Tukar Petani\",\"D\":\"Rasio Ketergantungan\"}', 'A', 'Gini Ratio (Rasio Gini) mengukur tingkat ketimpangan distribusi pendapatan/pengeluaran, dengan nilai 0 (merata sempurna) hingga 1 (timpang sempurna).', 1, '2026-07-12 12:36:58', '2026-07-12 12:36:58', NULL),
(33, 3, 'Penduduk digolongkan miskin oleh BPS apabila rata-rata pengeluaran per kapita per bulan berada di bawah...', '{\"A\":\"Upah Minimum Regional\",\"B\":\"Garis Kemiskinan\",\"C\":\"Indeks Harga Konsumen\",\"D\":\"PDRB per kapita\"}', 'B', 'Garis Kemiskinan adalah nilai rupiah pengeluaran minimum untuk memenuhi kebutuhan dasar; penduduk di bawahnya digolongkan miskin.', 1, '2026-07-12 12:36:58', '2026-07-12 12:36:58', NULL),
(34, 3, 'Nilai Tukar Petani (NTP) digunakan untuk mengukur...', '{\"A\":\"Tingkat kesejahteraan petani dari selisih harga jual hasil produksi dan harga barang yang dikonsumsi\\/biaya produksi\",\"B\":\"Jumlah petani di suatu wilayah\",\"C\":\"Luas lahan pertanian nasional\",\"D\":\"Harga pupuk bersubsidi\"}', 'A', 'NTP membandingkan indeks harga yang diterima petani dengan indeks harga yang dibayar petani, sebagai proksi kesejahteraan petani.', 1, '2026-07-12 12:36:58', '2026-07-12 12:36:58', NULL),
(35, 3, 'Perbandingan antara penduduk usia tidak produktif dengan penduduk usia produktif disebut...', '{\"A\":\"Rasio Jenis Kelamin\",\"B\":\"Rasio Ketergantungan\",\"C\":\"Angka Harapan Hidup\",\"D\":\"Laju Pertumbuhan Penduduk\"}', 'B', 'Rasio Ketergantungan (Dependency Ratio) membandingkan penduduk usia non-produktif (di bawah 15 dan di atas 64 tahun) terhadap penduduk usia produktif.', 1, '2026-07-12 12:36:58', '2026-07-12 12:36:58', NULL),
(36, 3, 'Selisih antara nilai ekspor dan nilai impor suatu negara disebut...', '{\"A\":\"Neraca perdagangan\",\"B\":\"Produk Domestik Bruto\",\"C\":\"Indeks Harga Konsumen\",\"D\":\"Nilai Tukar Petani\"}', 'A', 'Neraca perdagangan adalah selisih nilai ekspor dikurangi nilai impor; positif berarti surplus, negatif berarti defisit.', 1, '2026-07-12 12:36:58', '2026-07-12 12:36:58', NULL),
(37, 3, 'Laju Pertumbuhan Ekonomi suatu wilayah umumnya dihitung dari perubahan...', '{\"A\":\"Jumlah penduduk\",\"B\":\"PDRB atas dasar harga konstan\",\"C\":\"Indeks Pembangunan Manusia\",\"D\":\"Jumlah rumah tangga miskin\"}', 'B', 'Laju pertumbuhan ekonomi dihitung dari persentase perubahan PDRB atas dasar harga konstan antar periode, agar tidak terpengaruh inflasi.', 1, '2026-07-12 12:36:58', '2026-07-12 12:36:58', NULL);

